</tool_ip7i><tool_result_7wxs name="linux_ssh:linux_ssh_exec" status="success"><content>{"packageVersion":"0.1.0","success":true,"timeoutMs":10000,"exitCode":0,"timedOut":false,"output":"function slideInRows(container: Box, root: Box, selfToggle?: any): void {
  const rows = container.children.filter(c =>
    (c.id?.startsWith('title-') || c.id?.startsWith('file-'))
  );
  if (rows.length === 0) return;

  const totalH = container.height;
  const containerOrigYs = (container as any)._origYs as number[] | undefined;
  if (containerOrigYs && container.children.length === containerOrigYs.length) {
    container.children.forEach((c, j) => { c.y = containerOrigYs[j]; });
  }
  container.children.forEach(c => { c.opacity = 1; });
  rows.forEach(r => { r.transform.translateY = -totalH; });
  renderer?.setRoot(renderer!.getRoot()!);

  // ====== 盒子链：串行展开子容器，一个完再展开下一个 ======
  const subContainers = container.children.filter(
    c => c.id?.startsWith('expanded-') && (c as any)._fullHeight > 0
  );
  function expandNext(idx: number): void {
    if (idx >= subContainers.length) return;
    const child = subContainers[idx];
    const subFullH = (child as any)._fullHeight;
    child.children.forEach(c => { c.opacity = 0; });
    const tog = (child as any)._toggleBox;
    if (tog) tog.transform.rotate = 0;
    gsap.to(child, {
      height: subFullH,
      duration: 0.05,
      ease: 'power2.out',
      onUpdate: () => { renderer?.setRoot(renderer!.getRoot()!); },
      onComplete: () => {
        expandNext(idx + 1);
        slideInRows(child, root, tog);
      },
    });
  }
  expandNext(0);

  // ====== 当前容器 toggle 旋转（和文字链并行） ======
  if (selfToggle) {
    gsap.fromTo(selfToggle.transform, { rotate: 0 }, {
      rotate: Math.PI / 2,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => { renderer?.setRoot(renderer!.getRoot()!); },
    });
  }

  // ====== 文字链：逐行滑入（不阻塞盒子链） ======
  rows.forEach((row, i) => {
    const rowDelay = (i * 25) / 1000;
    gsap.to(row.transform, {
      translateY: 0,
      duration: 0.2,
      ease: 'power2.out',
      delay: rowDelay,
      onUpdate: () => { renderer?.setRoot(renderer!.getRoot()!); },
    });
  });","sessionId":"","error":""}</content></tool_result_7wxs>
